{"content":"#!/usr/bin/env python3
"""Tyson Mandela CV, monochrome v2 editions (black ground and white ground).

Same design as the monochrome v1 edition the owner approved: Inter, full-bleed ground,
17pt body, 104pt stacked name, 12pt section labels, two A4 pages. Only the words change.
Copy comes from a JSON file, so the wording can change without touching the layout.

Run:  PYTHONPATH= /usr/bin/python3 build_cv_mono_v2.py [copy.json]
Writes tyson-mandela-cv-mono-v2-{black,white}-a4.pdf to /root/twinthos-brain/audit/
"""
import html
import json
import sys
from weasyprint import HTML

THEMES = {
    'black': dict(BG='#0A0A0A', INK='#FFFFFF', BODY='#EDEDED', SEC='#A3A3A3', HAIR='#2E2E2E'),
    'white': dict(BG='#FFFFFF', INK='#0A0A0A', BODY='#1A1A1A', SEC='#5C5C5C', HAIR='#D4D4D4'),
}
OUTS = {
    'black': '/root/twinthos-brain/audit/tyson-mandela-cv-mono-v2-black-a4.pdf',
    'white': '/root/twinthos-brain/audit/tyson-mandela-cv-mono-v2-white-a4.pdf',
}
DEFAULT_COPY = '/root/.hermes/cache/scratch/cv-swarm/cv_v2_copy.json'

CSS = """
@page { size: A4; margin: 15mm 16mm 17mm 16mm; background: @BG@;
  @bottom-right { content: "TYSON MANDELA / " counter(page); font-family: 'Inter', sans-serif;
    font-size: 10pt; color: @SEC@; } }
html, body { background: @BG@; color: @BODY@; font-family: 'Inter', 'Helvetica', sans-serif;
  font-size: 17pt; line-height: 1.36; margin: 0; }
.name { font-size: 104pt; font-weight: 600; letter-spacing: -3pt; line-height: 0.88; color: @INK@; }
.head { font-size: 23pt; font-weight: 600; margin-top: 4mm; color: @INK@; }
.contact { font-size: 15pt; color: @SEC@; margin-top: 3mm; }
.summary { margin: 9mm 0 0 0; }
table.stats { width: 100%; border-collapse: collapse; margin-top: 8mm; }
table.stats td { width: 33%; vertical-align: top; padding: 3mm 4mm 0 0; border-top: 0.6pt solid @HAIR@; }
.num { font-size: 36pt; font-weight: 700; color: @INK@; line-height: 1; white-space: nowrap; }
.lab { font-size: 15pt; color: @BODY@; margin-top: 1.5mm; }
h2 { font-size: 12pt; font-weight: 700; letter-spacing: 0.3pt; text-transform: uppercase; color: @INK@;
  margin: 7.5mm 0 2.5mm 0; break-after: avoid; }
.role { margin-top: 3mm; }
.org, .meta, h2 { break-after: avoid; }
li { break-inside: avoid; }
.org { font-size: 22pt; font-weight: 700; line-height: 1.1; color: @INK@; }
.meta { font-size: 15pt; color: @SEC@; margin-top: 1mm; }
ul { margin: 3mm 0 0 0; padding-left: 6mm; }
li { margin-bottom: 3mm; font-size: 17pt; }
li::marker { color: @SEC@; }
.cap { margin-bottom: 1.5mm; break-inside: avoid; }
.cap b { font-weight: 700; color: @INK@; }
.tools { font-size: 17pt; line-height: 1.4; }
"""


def esc(s):
    return html.escape(s, quote=False)


def body_html(c):
    out = [
        '<div class="name">Tyson<br/>Mandela</div>',
        f'<div class="head">{esc(c["now"])}</div>',
        f'<div class="contact">{esc(c["contact"])}</div>',
        '<p class="summary">' + ' '.join(esc(s) for s in c['summary']) + '</p>',
    ]
    if c.get('stats'):
        cells = ''.join(f'<td><div class="num">{esc(n)}</div><div class="lab">{esc(l)}</div></td>'
                        for n, l in c['stats'])
        out.append(f'<table class="stats"><tr>{cells}</tr></table>')
    for sec in c['sections']:
        out.append(f'<h2>{esc(sec["heading"])}</h2>')
        for role in sec.get('roles', []):
            out.append('<div class="role">')
            out.append(f'<div class="org">{esc(role["org"])}</div>')
            out.append(f'<div class="meta">{esc(role["meta"])}</div>')
            if role.get('bullets'):
                out.append('<ul>' + ''.join(f'<li>{esc(b)}</li>' for b in role['bullets']) + '</ul>')
            out.append('</div>')
        for label, text in sec.get('caps', []):
            out.append(f'<div class="cap"><b>{esc(label)}.</b> {esc(text)}</div>')
        if sec.get('text'):
            out.append(f'<div class="tools">{esc(sec["text"])}</div>')
    return '\n'.join(out)


def css_for(t):
    s = CSS
    for k, v in t.items():
        s = s.replace(f'@{k}@', v)
    return s


def build(theme, copy):
    t = THEMES[theme]
    doc = ("<html><head><meta charset='utf-8'><title>Tyson Mandela, CV</title>"
           f"<style>{css_for(t)}</style></head><body>{body_html(copy)}</body></html>")
    HTML(string=doc).write_pdf(OUTS[theme])
    return OUTS[theme]


if __name__ == '__main__':
    path = sys.argv[1] if len(sys.argv) > 1 else DEFAULT_COPY
    with open(path, encoding='utf8') as fh:
        copy = json.load(fh)
    for th in ('black', 'white'):
        print('built', build(th, copy))
